import{_ as a,o as t,c as n,ag as o}from"./chunks/framework.BJFNwp4n.js";const u=JSON.parse('{"title":"Kafka","description":"The Kafka series on a local machine: concepts and selection, a single-node KRaft cluster started with one docker run, and a Golang project verifying produce, consume, consumer groups and offsets.","frontmatter":{"description":"The Kafka series on a local machine: concepts and selection, a single-node KRaft cluster started with one docker run, and a Golang project verifying produce, consume, consumer groups and offsets.","date":"2026-11-12T00:00:00.000Z","recommend":1,"tag":["Kafka"],"tags":["Kafka","Golang","Docker"],"categories":["Open Source"]},"headers":[],"relativePath":"en/open-source/kafka/index.md","filePath":"en/open-source/kafka/index.md"}'),r={name:"en/open-source/kafka/index.md"};function i(s,e,c,d,l,f){return t(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794441600000"},[...e[0]||(e[0]=[o('<h1 id="kafka" tabindex="-1">Kafka <a class="header-anchor" href="#kafka" aria-label="Permalink to &quot;Kafka&quot;">​</a></h1><p>This series walks through Kafka on a real local setup: what it is and why it is designed that way, when to use it; how to bring up a working single-node cluster with one <code>docker run</code>; and finally how to verify the basics with a Golang project.</p><ul><li><a href="./introduction.html">Kafka Concepts and When to Use It</a>: one end-to-end diagram tying together producer → topic → partition → offset → consumer group, replica roles, log storage and <code>acks</code> write acknowledgement, plus core capabilities, typical uses, performance and when to choose Kafka.</li><li><a href="./local-deployment.html">Running Kafka Locally</a>: the full <code>docker run</code> for a single-node KRaft (Kafka Raft) cluster, every setting explained, script management, a smoke test, data persistence and troubleshooting.</li><li><a href="./golang-verification.html">Kafka Verification with a Golang Project</a>: a cobra CLI (command-line interface), one subcommand per capability, covering topic management, sync/async producing, direct partition reads, an exact consumer-group limit, lag, and seven end-to-end assertions.</li></ul><p>Read them in order: concepts first, then get the cluster running, then verify it. If you already have a cluster, jump straight to the Golang verification page.</p>',4)])])}const g=a(r,[["render",i]]);export{u as __pageData,g as default};
